#define numWaves 26

mat2 rotate2D(float angle) {
    float s = sin(angle);
    float c = cos(angle);
    return mat2(c, -s, s, c);
}

vec3 renderScene(vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv -= 0.5;
    uv.x *= iResolution.x / iResolution.y;
    uv.y *= iResolution.y / iResolution.x;

    float time = iTime * 0.5;
    float dramaticTime = iTime * 0.2;

    uv *= rotate2D(sin(dramaticTime) * 0.25);

    float globalDistort = sin(iTime * 0.2 + uv.x * 3.0) * 0.23;
    uv.y += globalDistort;

    float modFreq = 9.0; 
    float modAmp = 2.2; 

    float basePower = 0.8;
    float power = basePower + sin(time * 0.15) * 0.35; 
    float baseYAmp = 1.2;
    float yAmp = baseYAmp + cos(time * 0.35) * 0.6; 

    vec3 color = vec3(0.0);

    for(int i = 0; i < numWaves; i++) {
        float phase = float(i) * 2.0 * 3.14159 / float(numWaves) + sin(dramaticTime) * 0.5;
        float freq = 11.0 + float(i) * 2.5;
        float baseAmp = 0.28 / float(i + 1);
        float amp = pow(baseAmp * (1.0 - abs(uv.y) * yAmp), power);
        vec3 waveColor = vec3(
            sin(phase + time * 0.2) * 0.55 + 0.45,
            sin(phase + time * 0.3) * 0.55 + 0.45,
            sin(phase + time * 0.4) * 0.55 + 0.45
        );
        float modulation = sin(uv.x * modFreq + cos(time)) * modAmp;
        float wave = sin((uv.x + sin(time + phase) * 0.15) * freq + time + modulation) * amp;
        float dist = distance(uv, vec2(uv.x, wave));
        color += waveColor * smoothstep(0.012, 0.0, dist);
    }

    vec2 uvReversed = vec2(uv.x, -uv.y);
    vec3 colorReversed = vec3(0.0);

    for(int i = 0; i < numWaves; i++) {
        float phase = float(i) * 2.0 * 3.14159 / float(numWaves) - sin(dramaticTime) * 0.5;
        float freq = 11.0 + float(i) * 2.5;
        float baseAmp = 0.28 / float(i + 1);
        float amp = pow(baseAmp * (1.0 - abs(uvReversed.y) * yAmp), power);
        vec3 waveColor = vec3(
            sin(phase + time * 0.2) * 0.55 + 0.45,
            sin(phase + time * 0.3) * 0.55 + 0.45,
            sin(phase + time * 0.4) * 0.55 + 0.45
        );
        float modulation = sin(uvReversed.x * modFreq + cos(time)) * modAmp;
        float wave = sin((uvReversed.x + sin(time + phase) * 0.15) * freq + time + modulation) * amp;
        float dist = distance(uvReversed, vec2(uvReversed.x, wave));
        colorReversed += waveColor * smoothstep(0.012, 0.0, dist);
    }

    vec3 finalColor = mix(color, colorReversed, 0.5);

    vec2 q = fragCoord.xy / iResolution.xy;
    q = q * 2.0 - 1.0;
    float vignette = 1.4 - dot(q, q);
    vignette = smoothstep(0.0, 0.65, vignette);
    finalColor *= vignette;

    finalColor = pow(finalColor, vec3(1.5)) * 0.9;

    return finalColor;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec3 colorOriginal = renderScene(fragCoord);
    vec3 colorHoriz    = renderScene(vec2(iResolution.x - fragCoord.x, fragCoord.y));
    vec3 colorVert     = renderScene(vec2(fragCoord.x, iResolution.y - fragCoord.y));
    vec3 colorBoth     = renderScene(vec2(iResolution.x - fragCoord.x, iResolution.y - fragCoord.y));
    vec3 finalColor = (colorOriginal + colorHoriz + colorVert + colorBoth) / 4.0;
    fragColor = vec4(finalColor, 1.0);
}
